// Made by pipeline/tools/lore-codex.py from docs/lore/codex/: edit the codex there and run the script again.
// The Codex book "peoples": each page as blocks (see lore-codex.py).

import type { CodexPage } from './codex';

export const PAGES: Record<string, CodexPage> = {"peoples/README": {"title": "The peoples of the Dial", "sub": "", "blocks": [["p", "Twelve peoples live on the Dial. So the Dial is not only human: **four peoples are human**, each with its own build, dress, skin, hair and marks; **three are human peoples the Fall changed** (eyes that shine, ash-grey skin, horns); and **five are not human at all**. Back to the codex."], ["p", "Every hero belongs to exactly one people (the lore check holds to it). On the game's Play card the people stands between the faction and the home: *Noonsworn · Aubade folk · from Aubade*."], ["h", 2, "The twelve"], ["t", ["People", "Kind", "Home", "In one line"], [["[Aubade folk](peoples/aubade)", "human", "Aubade", "Tall, golden-brown, long hair bound with gold thread; the dawn line on the sworn. They rang the sun up, and lost their choir when it fell"], ["[Dune folk](peoples/dune)", "human", "The Sands", "Lean, dark-skinned, kohl to the temples, layered linen. The oldest court; they call the sun the Father"], ["[Gloaming folk](peoples/gloaming)", "changed", "Gloaming", "Pale, blue-grey, eyes that shine back light. A century of dusk made them a people of the night"], ["[Northerners](peoples/north)", "human", "Frostfall", "Broad, dark-skinned, white-braided, star lines on jaw and hands; the lake-born are frost-pale. They measure everything"], ["[Coast folk](peoples/coast)", "human", "The Drowned Coast", "Wiry, sea-tanned, salt-bleached, tide lines on the forearms. They read the weather and sail anyway"], ["[Kilnborn](peoples/kiln)", "changed", "The Deep", "Short, broad, ash-grey skin, ember seams at the forge. The sun's heat came up through their rock"], ["[Wood folk](peoples/wood)", "changed", "The Walking Wood", "Ruddy, moss-eyed; the sworn grow horns. They follow a forest that walks"], ["[Mole-folk](peoples/mole)", "other", "The deepest seams", "A mole's head, velvet fur, gilded claws. The Deep's first people, who call themselves the Loam"], ["[The Ninefold](peoples/ninefold)", "other", "The Keep of Nine", "A great cat's head, lynx or lion; nine lives. Knights of every court, fewer every year"], ["[Briarkin](peoples/briar)", "other", "The Underbough", "Pointed ears, eyes of one colour, a court's sign. The fae of the Wood, who fade when forgotten"], ["[The Long Dead](peoples/longdead)", "other", "The ossuaries", "Vellum skin on bone, eyes of cold fire. The dead whose purpose would not lie down"], ["[The Fallborn](peoples/fallborn)", "other", "Where the Fall made them", "Three kinds: the Embers (sparks of the sun), the Cast (shadows that walked), the Unmade (what came through the Tear)"]]], ["h", 2, "How many heroes in each"], ["t", ["People", "In the game", "New", "All"], [["Aubade folk", "5", "2", "7"], ["Dune folk", "3", "4", "7"], ["Gloaming folk", "3", "1", "4"], ["Northerners", "5", "2", "7"], ["Coast folk", "6", "2", "8"], ["Kilnborn", "4", "3", "7"], ["Wood folk", "3", "1", "4"], ["Mole-folk", "1", "1", "2"], ["The Ninefold", "1", "1", "2"], ["Briarkin", "4", "2", "6"], ["The Long Dead", "2", "1", "3"], ["The Fallborn", "3", "0", "3"], ["**All**", "**40**", "**20**", "**60**"]]], ["p", "Of the forty in the game, 19 are of the four human peoples, 10 of the three changed ones and 11 of the five others."], ["h", 2, "Where the peoples meet"], ["p", "The Ring is the one place every people meets on equal terms, under the Truce. Elsewhere they keep to their realms, with these crossings: the Brass Road (Kilnborn, mole-folk, Dune folk), the Frostfall road (Northerners, Briarkin, Wood folk), the night roads (Gloaming folk, the Cast, the Long Dead), the sea (Coast folk and everyone who can pay), and the Field of Banners, where all of them once fought and the Ninefold still keep their old keep."]]}, "peoples/aubade": {"title": "Aubade folk", "sub": "Human. The people of the morning cliffs, who ring the sun up.", "blocks": [["h", 2, "Origin"], ["p", "The Aubade folk say they were the first to be woken by the sun, because their cliffs face the morning and the light reached them before it reached anyone. Their oldest songs begin with a woman on a cliff edge who sang back when the sun rose, and the sun, pleased, came up a little faster the next day. From her, they say, come the bells, the choir and the Hymn of Noon. The Hourkeepers' charts put the first town on the cliffs about 1,100 years before the Fall, a fishing village that had learned to read the Tower's shadow from across the bay."], ["p", "For four hundred years before the Fall the Aubade folk sent a choir of a hundred up the Tower every day to sing the Hymn at its top, and they were proud of it in the way a family is proud of a lamp it has never let go out. When the sun fell during the Hymn, it fell on their pride first."], ["h", 2, "Homeland"], ["p", "[Aubade](realms/aubade), the white city on the eastern cliffs, at the first hour of the Dial; the shrine cliffs below it where the wrestlers train; the terraces of vines and olives inland; the Dawn Stair down to the harbour of Lowlight. Many Aubade folk live at the Ring too, as the Truce's couriers, clerks and cooks, because the road from Aubade to the Tower is the oldest paved road on the Dial."], ["h", 2, "Body"], ["p", "Tall and long-limbed, with a straight back they are taught as children (\"stand like a bell rope\"). Skin warm golden-brown to olive, freckling across the nose in summer. Hair dark gold to black, never cut short except in mourning, worn long and bound with gold thread: one thread for each oath kept. Eyes brown or hazel, often light at the rim. The sworn of the Noonsworn carry the **dawn line**, a thin gold tattoo from the middle of the brow down the bridge of the nose, put on at dawn on the day of the oath."], ["h", 2, "Lifespan and the Fall"], ["p", "They live about eighty years. The Fall touched them twice. Every Aubade child alive that week is Noon-touched, as everywhere, and many of Aubade's elders are; and the choir did not come home. Of the hundred who sang the Hymn on the day, two came down the Tower: [Cantor](heroes/cantor) and [Mum](heroes/mum). Every family in Aubade lost a singer, and the city has kept a year of mourning a hundred times over: the bells are rung every morning, and the hundredth bell is rung short, for the choir."], ["h", 2, "Culture"], ["p", "The Aubade folk are early risers, oath-takers and keepers of rhythm. A child's first gift is a small bell; a marriage is a duet; a death is a verse. They argue in public and forgive in private. Their houses are whitewashed every spring and face east with a window that is never shuttered. Their food is bread, olives, white cheese, figs and a black honey from the cliff flowers, and the dawn meal is the important one. They make the best bronze on the Dial outside the Deep, and the best paper outside Frostfall."], ["p", "Since the Fall the city has become harder. The Noonsworn ([faction](factions/noonsworn)) run it in all but name, and an Aubade child who says the sun should not be hung again will be listened to kindly and not invited back. The poorer quarters under the cliff, where the light comes last, are less certain, and send more children to the Ring than to the barracks."], ["h", 2, "Faith"], ["p", "The Aubade folk do not worship the sun so much as keep it company. Their faith is the **Oath of the Dawn**: that every night ends, that the end can be helped, and that whoever helps it must keep faith with it every morning. The temples are bell towers. There are no priests, only ringers, singers and the sworn. Since the Fall most Aubade folk believe the sun can be hung again and that it is their duty to do it. A quieter teaching, the Low Verse, holds that the sun fell because the Hymn was sung for pride and not for company, and that it will come back when it is asked kindly. The Noonsworn do not forbid the Low Verse. They simply never ring for it."], ["h", 2, "Names"], ["p", "Given names are bell-words and light-words in the old cliff tongue, often softened: Auriel (\"first light\"), Campana (\"bell\"), Orren (\"bearer\"), Cantor (\"singer\"), Pip (a courier's nickname: his given name is Pellam-of-the-Stair, which nobody calls him). Family names are the house's bell: Auriel of the White Bell, Orren of the Low Lantern. A sworn hero drops the family bell and takes the oath's name."], ["h", 2, "How they fight"], ["p", "In shield walls of white and gold, with long swords and longer patience: the Aubade way is to hold, then break out all at once, \"as the dawn does\". Their paladins wear plate and wings of plates, and their shields are made to burst outward when broken, an old smith's trick that became a creed. The shrine wrestlers below the cliffs fight inside a rope circle and count a fall as a lesson. The choir fought only once, at the Fall, and lost."], ["h", 2, "Heroes and Climb people"], ["ul", ["**In the game:** [Auriel](heroes/auriel), [Cantor](heroes/cantor), [Big Yoko](heroes/big-yoko), [Mum](heroes/mum), [Pip](heroes/pip).", "**New:** Campana, Orren.", "**On the Climb:** none of the Climb's chapters is Aubade. The War's White Sister was born in Lowlight and went to the Field as a girl to nurse the azure wounded ([the War](climb/war))."]], ["h", 2, "Ties to other peoples"], ["p", "Old friends of the Northerners, who share their wish for a sun over the Tower; uneasy with the Dune folk, whose king calls the sun his father; cold to the Gloaming folk since the Fall, though before it Aubade's choir and Gloaming's mirror-makers traded songs for glass every midsummer. They trade bells for copper with the Kilnborn and do not trust the copper."]]}, "peoples/briar": {"title": "Briarkin", "sub": "Not human. The fae of the Walking Wood, in their courts under the Underbough.", "blocks": [["h", 2, "Origin"], ["p", "The Briarkin were in the Wood before the Wood folk, and possibly before the Wood. Their story is that they are the forest's dreams, which got up one night and did not lie down again. The Hourkeepers have no date for them: the first chart that mentions the Wood already mentions \"the small people in the glades who will not be counted\". They live in **courts**, each a household of a kind, under the **Underbough**: the deep glades and hollow hills of the Walking Wood, where the paths of the Wood folk do not go."], ["h", 2, "Homeland"], ["p", "The Underbough, deep in the [Walking Wood](realms/wood). Each court has its glade: the Acorn court under the great oaks, the Moth court in the night meadows, the Hive court in the hive-trees, the Fox court in the thickets round Gloaming (the only court outside the Wood), and the Spindle court, which is wherever its spinners sit. Since the Wood began to walk, the courts move with it, and the Underbough is never in the same place two years running."], ["h", 2, "Body"], ["p", "Briarkin look like people, nearly, and the nearly is the point. Their ears are long and **pointed**. Their eyes are **one colour from lid to lid**, with no white: leaf green, amber, silver, black. Their skin is any colour a forest has, from birch-pale to bark-brown, and faintly patterned like light through leaves. They are small or tall as they please, within a span: a Briarkin can look ten or seventy, and keeps the age that suits them. And each court has its **sign**, grown, not worn:"], ["ul", ["the **Acorn** court: small and quick, with nut-brown skin and green eyes ([Pim and Pom](heroes/pim-and-pom));", "the **Moth** court: great soft wings that fold like a cloak, and feathered antennae (Vela);", "the **Fox** court: a fox's mask of a face by night, and one tail by day, nine in the old stories (Kohaku);", "the **Hive** court: chitin plates at the shoulders and brow, faceted eyes, two pairs of wings ([Sirix](heroes/sirix));", "the **Spindle** court: silver eyes, long clever fingers, and great age worn lightly ([Grandma Ironknit](heroes/grandma-ironknit))."]], ["p", "A Briarkin of **no court** has left theirs, and hides the sign or wears it plainly, as they choose ([The Great Zambini](heroes/the-great-zambini))."], ["h", 2, "Lifespan and the Fall"], ["p", "Nobody knows. Briarkin do not die of age; they **fade**, when nothing remembers them, and they are reborn when a story about them is told again, which they do not like to discuss. The Fall touched them more than anyone guessed. The Wood began to walk, and the courts with it; the old treaty with the Wood folk, which said the fae kept to the glades, had nothing to say about glades that moved. And something worse: in the first winter after the Fall, Briarkin children began to be born **swapped**, two for one, each a half of a single life. Pim and Pom were the first. The courts were frightened, and left them on a doorstep."], ["h", 2, "Culture"], ["p", "Courtly, playful, ruthless and bound by rules nobody else can see. A Briarkin will not lie, will not refuse a fair bargain, will not cross a line of salt or cold iron, and will not give their full name, because a name given can be taken (the Fox court lives by taking them). They love games, riddles, music, gifts that are not quite gifts, and above all **audiences**: a Briarkin who is not watched grows thin. They eat honey, dew, flowers, cream, and whatever is left out for them, and take offence if nothing is. Their crafts are glamour (the art of seeming), silk, wax, wine from flowers, and promises."], ["h", 2, "Faith"], ["p", "They have none, they say, because they are what others have faith in. In truth they keep the **Telling**: everything that is remembered is alive, and everything forgotten fades, so the holiest act is to tell a story well. They fear the Tower, which they believe swallows stories whole, and the [Unmade](peoples/fallborn), which unmakes them."], ["h", 2, "Names"], ["p", "Every Briarkin has a true name, never given, and a **use-name**, given freely and often changed: Pim, Pom, Vela, Kohaku (a fox name meaning amber), Sirix, and Ironknit (the Spindle court's word for a spinner who has chosen to live among mortals). The Great Zambini is a use-name of the third kind: a stage name worn over a use-name worn over a true one."], ["h", 2, "How they fight"], ["p", "By not fighting fair, which they consider the only honest way. Glamour, tricks, swaps, sleep, stolen names, stings, threads and traps; they win by making you fight the wrong thing. Struck with cold iron, they flinch."], ["h", 2, "Heroes and Climb people"], ["ul", ["**In the game:** [Pim and Pom](heroes/pim-and-pom) (Acorn), [Sirix](heroes/sirix) (Hive), [Grandma Ironknit](heroes/grandma-ironknit) (Spindle), [The Great Zambini](heroes/the-great-zambini) (no court).", "**New:** Kohaku (Fox), Vela (Moth).", "**On the Climb:** the Wood's thorn sprites and wisps are Briarkin who faded inside the Tower and half came back ([bestiary](climb/bestiary)); the Charm-Pedlar trades with the courts and wears their charms against them."]], ["h", 2, "Ties to other peoples"], ["p", "Treaty-friends of the Wood folk; old players of the Ninefold, who enjoy their games; curious about the Northerners, who keep writing them down (which the Briarkin secretly love, because being written down is being remembered); afraid of the Long Dead, who remember too well, and of the Unmade."]]}, "peoples/coast": {"title": "Coast folk", "sub": "Human. The people of the Drowned Coast and the Spires, who read the weather and sail anyway.", "blocks": [["h", 2, "Origin"], ["p", "The Coast folk have always lived where the land runs out: fishers and pilots on the south-eastern shore of the Dial, and the tower-dwellers of the Spires, the broken sky towers that stand in the sea off the coast. Nobody built the Spires, as far as the Coast folk know, and they have lived in them as long as they have lived anywhere: there are rooms in the Spires that have been lived in for a thousand years and rooms nobody has found the door to. The Coast folk say the land was given to the others and the sea and the sky to them, and that this was the better deal."], ["h", 2, "Homeland"], ["p", "[The Drowned Coast](realms/coast), at the fifth hour: the Drowned Harbour, which was the great port of Sallowmouth before the sea came in over it; the harbour towns behind it (Saltreach, Tern's Landing); the Lantern Coast, with a lighthouse on every point; the sea temple; and the Spires, standing in the sea. Coast folk crew every ship on the Outer Sea and most of the Truce's ferries."], ["h", 2, "Body"], ["p", "Wiry and quick, with strong forearms. Skin sea-tanned, from light bronze to brown, lined early round the eyes. Hair salt-bleached from sand to near white, and often dyed sea-green or blue with kelp. Eyes grey, green or brown. The marks of the people are the **tide lines**, thin blue tattoos round the forearms, one for each great flood the wearer has lived through (a Coast elder may have twenty), and **sea-glass** worn in the ears and hair. The Spire-born are lighter and longer-limbed than the harbour folk, and can stand on a ledge in a gale without holding on."], ["h", 2, "Lifespan and the Fall"], ["p", "About seventy years; the sea takes many sooner. The Fall came to them as water. The sun's heat lifted the sea, and on the day of the Fall the sea came in over Sallowmouth and did not go out: the Drowned Harbour. Half the city drowned that afternoon. Since then the weather has had no master, the storms come when they like, and the Coast folk have become the Dial's readers of the sky, because they had to. Every Coast child learns to swim before they walk, and the first tide line is drawn at the first flood."], ["h", 2, "Culture"], ["p", "Practical, generous, loud and superstitious. The Coast folk share everything that floats and argue about everything that does not. A boat is a family; a family is a crew; a crew elects its captain every spring. They whistle to call the wind and never whistle indoors. They eat fish, shellfish, seaweed bread, oranges from the terraces behind the coast, and a fiery fish soup that is the true test of a guest. Their crafts are boats, rope, sails, glass floats, kites and weather-glasses. Since the Fall they have become inventors too, of balloons and lightning rods and things nobody else would try."], ["h", 2, "Faith"], ["p", "The **Tide**. The sea comes in and goes out, and so do lives, fortunes and storms; the wise person keeps their floor clean and their boat tied. The sea temple of the Drowned Harbour is the centre of the faith, and its keeper ([Gus](heroes/gus)) is the nearest thing the Coast folk have to a priest, which he denies. The faith has no view on the sun. Most Coast folk would back whoever can mend the sky and give them back seasons, and say so."], ["h", 2, "Names"], ["p", "Short, bright names, bird names and wind names: Marin, Kaia, Zephyr, Lian, Morwen, Gus (short for Augustin, which only his mother used). Surnames are boats or weather: Barry Cloudsley, Tam Netmender, Ilse Fairwind. Professor Puff's name is his own choosing, from the sound his balloons make; his birth name is in the Spires' register and he will not say it."], ["h", 2, "How they fight"], ["p", "At sea, by boarding, with short blades, hooks and nets; on land, as skirmishers who never stand still. Their fighters use the weather: the storm callers of the Spires bring down lightning, the tide dancers turn the water, and the Spire-born fight on the wind itself. A Coast fighter wins by being somewhere else when the blow lands."], ["h", 2, "Heroes and Climb people"], ["ul", ["**In the game:** [Marin](heroes/marin), [Kaia](heroes/kaia), [Zephyr](heroes/zephyr), [Barry Cloudsley](heroes/barry-cloudsley), [Professor Puff](heroes/professor-puff), [Gus](heroes/gus).", "**New:** Morwen, Lian.", "**On the Climb:** the Sea's five, the Bell-Warden, the Net-Father, the Lamp-Bearer, the Tide-Broker and the Coral-Pedlar; and the drowned dockers and their kin, who were Coast folk the morning the water came ([the Sea](climb/sea))."]], ["h", 2, "Ties to other peoples"], ["p", "Friends of the Wood folk (rain for the Wood, timber for the ships); trade with everyone; quarrel with the Dune folk over the Sands' storms and the Sands' king; mistrust the Kilnborn's Gaol of Oaths under their harbour; admire the Northerners and think them slow."]]}, "peoples/dune": {"title": "Dune folk", "sub": "Human. The people of the Sands, children of the oldest court on the Dial.", "blocks": [["h", 2, "Origin"], ["p", "The Dune folk came out of the east when the Sands were grass, say their tomb paintings, and stayed when the grass went, because the sun stayed. They count their history by kings: the first king took the crook about 600 years before the Fall, and the Throne has passed from hand to hand, and lately from head to head, ever since. They were caravan people first and city people second, and every Dune family still keeps one camel saddle in the house, even if nobody in it has ridden for a century."], ["h", 2, "Homeland"], ["p", "[The Sands](realms/sands), at the third and fourth hours of the Dial: Tamerit, the city of the Throne, on the river Sefet between the Glass Flats and the Storm Canyon; the Valley of Lids, where the kings are buried; the oases along the Brass Road; the caravan towns of the Storm Canyon. Since the Fall a good many Dune folk live on the Field and at the Ring, where the Truce's cooks, clerks and caravan masters are often from the Sands."], ["h", 2, "Body"], ["p", "Lean, long in the neck and the fingers, made to lose little water. Skin dark bronze to deep brown. Hair black and thick, shaved by the court and the priests, worn in fine braids by everyone else and bound with copper. Eyes dark, and lined with kohl out to the temples, men and women alike, against the glare; the court adds gold leaf on the lids. Hands are often hennaed in the pattern of the wearer's house."], ["h", 2, "Lifespan and the Fall"], ["p", "About seventy-five years in the cities, less in the caravans. The Fall came to them as heat. The Sands say the sun fell into their dunes, not the Tower's foot, and the sand is still warm a hand's depth down even in the coldest night. Glass grew on the Flats that day where the heat struck, a whole plain of it. The Noon-touched of the Sands are many, and include their king. The Fall also cost them their queen: the Sands blamed Asenet, who ruled that year, and the crown went to her brother [Sefu](heroes/sefu)."], ["h", 2, "Culture"], ["p", "The oldest manners on the Dial: a guest is given water before a name is asked, a quarrel is settled before the evening meal, and every family keeps its dead in the house for three days. Trade is honour: a broken bargain is a broken family. They are great record keepers, though their records are of the dead (the tombs are libraries). The food is flatbread, dates, lentils, goat, and a sour drink of fermented barley that every foreigner is made to try once. Their crafts are glass from the Flats, linen, turquoise, perfume and embalming, which is an art and a medicine both."], ["p", "The Throne is everything. Even the Dune folk who hate Sefu bow to the crook, because a Sands without a king, they say, is just sand. Since the curse on the crown they have become a people who watch their rulers' heads."], ["h", 2, "Faith"], ["p", "The kings of the Sands called the sun their father, and the Dune folk call it **the Father** still. Their faith says the sun did not fall but **came home**: it walked down into the Sands to rest among its children, and it will rise again from them in a king. The priests weigh the hearts of the dead against a feather so that the Father knows whom to take with him when he rises. The tombs are holy, and the veiled priestesses who guarded them with their eyes are remembered with fear and love. A smaller faith of the caravans, the Way of Water, holds that the sun is only a lamp, and that what matters is the next well."], ["h", 2, "Names"], ["p", "Short names of one or two syllables in the old desert tongue, with a meaning in the house's trade: Sefu (\"sword\"), Asenet, Nebet (\"lady\"), Sahar (\"dawn-glare\"), Ramet (\"gate\"), Lithea (a priestess name, never given to a child). A Dune person also carries a **house name** after the given one, said only at weddings, funerals and in court: Sefu of the Crook, Nebet of the Scale. Embalmers take no name at all when they put on the mask, and are called by their trade: [Vitriol](heroes/vitriol) is a word for the oil he uses."], ["h", 2, "How they fight"], ["p", "From horseback and camelback, with the bow and the curved blade, in loose skirmish lines that fade into the heat. The Throne's guard fights on foot in bronze scales and lion hoods behind long spears. Their priests fight with poison and with the dead, their archers with the mirage. A Dune army never gives battle at noon."], ["h", 2, "Heroes and Climb people"], ["ul", ["**In the game:** [Sefu](heroes/sefu), [Vitriol](heroes/vitriol), [Madame Cleaver](heroes/madame-cleaver) (a caravan cook's daughter, who went to the Banners' camps with her mother's cleaver).", "**New:** Lithea, Nebet, Sahar, Asenet.", "**On the Climb:** the Sands' five, the Star-Reader, the Storm-Counter, the Beacon-Keeper, the Silk-Merchant and the Glass-Seller; and the caravan raiders and slingers, who are Dune folk caught in the storm ([the Sands](climb/sands))."]], ["h", 2, "Ties to other peoples"], ["p", "Old trade partners of the Kilnborn on the Brass Road; allies of convenience with the Gloaming folk; rivals of the Aubade folk over whose sun it is; impatient with the Coast folk, whose sailors laugh at camels. They welcome the Ninefold, who have kept their gate for three generations."]]}, "peoples/fallborn": {"title": "The Fallborn", "sub": "Not born. The beings the Noonfall made or let in: the Embers, the Cast, and the Unmade.", "blocks": [["p", "The Fallborn are not a people in the way the others are. They have no homeland, no children and no common tongue. What they share is that **none of them existed before the Fall**. The Hourkeepers group them because they must be written down somewhere, and the Fallborn have accepted the name, because it is true. There are three kinds, and they could hardly be less alike."], ["h", 2, "The Embers"], ["p", "**Origin.** When the sun cracked and fell, sparks of it scattered over the Dial. Most went out. A few did not, and became something. The Embers are those sparks, grown into beings with a will. The greatest are **Ash and Ember**, the sun's two last embers, who burn in the Cinder Pit beneath the Tower. The first to walk was [Anka](heroes/anka): a spark that fell into the sea off the Drowned Coast and walked out of the surf the next morning as a woman. Others are smaller: the Hourkeepers count nine Embers on the Dial, most of them no larger than a candle-flame that thinks."], ["p", "**Body.** An Ember takes a shape from the first thing it sees, and Anka's first sight was a dancer on the shore. Embers look like people of flame and gold: skin warm and bright, glowing faintly at its edges (the line of the jaw, the fingers, the hair's roots); hair like flame, dark red to gold; eyes like coals. They are warm to the touch, hot when angry, and they burn when they die, and rise from what they leave on the ground."], ["p", "**Life and fire.** An Ember does not age: each fire makes it new, about twenty in a human's eyes. It can be put out only by cold, water held long enough, or by being kept from its ashes. It remembers every life."], ["h", 2, "The Cast"], ["p", "**Origin.** At the moment the sun fell, its last light threw every shadow on the Dial long and hard across the ground. A few of those shadows did not come back when the light changed. They peeled off their walls and walked. These are **the Cast**. The first and best known is [Nyx](heroes/nyx), thrown across the wall of the Night Temple in Gloaming. The Court of Dusk took the Cast in, since nobody else would, and most of them serve it."], ["p", "**Body.** A Cast looks like the shadow of a person standing up: a slim human figure of matte, light-drinking black, with a thin hard edge of violet where light catches it, and no face at all; a pale slit where eyes would be, mint or white. They cast no shadow of their own. They fade when they are left alone, and come back sharper when someone looks for them."], ["p", "**Life.** They do not age. They are hurt by full light and by being forgotten, and nobody knows what kills them. The Hourkeepers count perhaps forty."], ["h", 2, "The Unmade"], ["p", "**Origin.** When the sun fell, it tore the sky above the Tower: the Tear, black with a burning pink edge. Through it, on the day of the Fall, came something the Dial has no word for. The Hourkeepers call it **the Unmaker**; the codex uses its name in the Ring, [Oblivion](heroes/oblivion). It is the only one of its kind that has walked the Dial. Smaller things come through the Tear at times, rifts that drift and pull and close, and the Hourkeepers call all of them the Unmade."], ["p", "**Body.** It wears a shape, not a body: a towering knight in black plate, cracked with glowing pink rifts, a horned helm with one burning slit, a ragged cloak whose hem breaks into floating shards. What is inside the plate, if anything, nobody has seen."], ["p", "**Life.** Not born, not ageing; whatever it touches stops being able to end. Wick, Tempo and Thessa have sworn to send it back."], ["h", 2, "Culture, faith, names"], ["p", "The Fallborn share none. Anka keeps the dances of the shore and the faith of the Noonsworn, who call her the sun's promise. The Cast keep the Court's manners and the Vigil, and take names given them by whoever first named them. The Unmaker keeps nothing, and its name is the Ring's. The only thing the Fallborn have in common is a question every one of them is asked, and none can answer: what were you, before?"], ["h", 2, "How they fight"], ["p", "The Embers burn and rise; the Cast fade and strike from the fade; the Unmade pull, and what is pulled in does not always come back."], ["h", 2, "Heroes and Climb people"], ["ul", ["**In the game:** [Anka](heroes/anka) (an Ember), [Nyx](heroes/nyx) (of the Cast), [Oblivion](heroes/oblivion) (the Unmade).", "**On the Climb:** **Ash and Ember**, the crowns of floors 20 and 50, are the greatest of the Embers; **the Heart of Noon**, the crown of floor 30, is what is left of the sun itself, and the Hourkeepers will not call it Fallborn because it was there first ([rulers](climb/rulers))."]], ["h", 2, "Ties to other peoples"], ["p", "The Embers are loved by the Aubade folk and feared by the mole-folk and the Long Dead. The Cast belong to the Gloaming folk. The Unmade has no ties, and every people on the Dial has a reason to want it gone."]]}, "peoples/gloaming": {"title": "Gloaming folk", "sub": "Human, changed by a hundred years of dusk. The people whose eyes shine back.", "blocks": [["h", 2, "Origin"], ["p", "Before the Fall the Gloaming folk were an ordinary people of the north-western hills: mirror-makers, vintners, keepers of the night roads, and a nobility that had always been a little proud of being pale. Gloaming stood at the eleventh hour of the Dial, where the Tower's shadow came at evening, and its people had a reputation for late nights and good wine. Their nobles kept the ossuaries under the castle-city with the help of the [Long Dead](peoples/longdead), and paid them in the only coin the Long Dead take: remembrance."], ["p", "On the day of the Fall the light left Gloaming first and came back last. For the first year after the Fall there was no full day there at all, only a long blue dusk. The people who lived through it changed."], ["h", 2, "Homeland"], ["p", "[Gloaming](realms/gloaming), the castle-city round the Night Temple on the north-western heights, and the dusk valleys around it: the vine terraces, the mirror quarter, the village of Lantern-under-Hill, the night roads that run east to Frostfall and south to the Walking Wood."], ["h", 2, "Body"], ["p", "Tall, narrow and long-handed, with fine bones. Skin very pale with a blue-grey cast, as if lit by a cold lamp; it does not tan and burns in an afternoon. Lips dark, almost violet. Hair black, silver or a deep violet that is their own and not a dye. The mark of the people is the eyes: since the long dusk, a Gloaming child's eyes **shine back** light like a cat's, silver or violet, so that a crowd of Gloaming folk at night is a field of small moons. They see well in the dark and badly at noon, and squint in the Ring's light."], ["h", 2, "Lifespan and the Fall"], ["p", "About ninety years, and they age slowly after forty, which the Court calls breeding and the Hourkeepers call the dusk. Besides the eyes, the long dusk gave them a horror of noon and a hunger for the night that the old Gloaming did not have. A few of them, the ones who went furthest into the dark, found other hungers: [Vesper](heroes/vesper) has lived a hundred years on blood and is not Noon-touched at all; she stopped. The stone-woken are rarer still: Gloaming folk who were turned to stone and woke again at dusk, as Corbel did."], ["h", 2, "Culture"], ["p", "A people of the evening. The working day begins at sunset; the markets open with the lamps; children are told to come home before the morning. They make the best mirrors and the best wine on the Dial, and the most elaborate manners: a Gloaming conversation is half compliment, and the other half is a knife. The nobility are bound by houses (the Countess's house, the Mirror house, the house of Bells) and by debts, and no one of them is without both. The commons are night-road wardens, gravediggers, glaziers and grape-pickers, and are proud, quiet and a great deal more honest than their lords."], ["p", "The Court of Dusk ([faction](factions/dusk)) is the nobility's answer to the Fall, and most Gloaming folk support it: a new sun would hurt them. They are not cruel because they are pale. They are frightened, and well dressed."], ["h", 2, "Faith"], ["p", "The **Vigil**. The Gloaming folk keep watch for the dead, and believe that the night is when the Dial remembers. The Night Temple holds no god but a great dark mirror that reflects nothing, and before it the names of the dead are said aloud each night. Since the Fall the Vigil has added a teaching: that the dusk is not an ending but an age, the **Long Evening**, and that it is as holy as any noon. The Court has made this teaching law."], ["h", 2, "Names"], ["p", "Long, soft names with many vowels: Vesper, Silvane, Opaline, Corbel, Moraine, Ysolt. Nobles add the house: Silvane of the Mirror house, Vesper of the Countess's house. The commons add a trade: Corbel the Templeguard. Children born in the long dusk of year 0 were all given names of evening things, and that generation is still called the Vespers, after the Countess."], ["h", 2, "How they fight"], ["p", "At night, in small bands, with rapiers, crossbows and mirrors: a Gloaming duellist uses light as a weapon, catching a lamp in a glass and throwing it in your eyes. The Court's soldiers are few and good. Its real strength is its allies (the Long Dead's bone walls, the Cast's knives) and its information."], ["h", 2, "Heroes and Climb people"], ["ul", ["**In the game:** [Vesper](heroes/vesper), [Silvane](heroes/silvane), and [Opaline](heroes/opaline), Silvane's younger sister, who went south to the Deep and to the Noonsworn.", "**New:** Corbel, stone-woken.", "**On the Climb:** none of the people; the War's Crow King, a ruler of floor 46, was a Gloaming lord who rode to the Banners ([rulers](climb/rulers))."]], ["h", 2, "Ties to other peoples"], ["p", "Bound to the Long Dead by old debts and older love; allied with the Dune folk; served by the Cast; at war in all but name with the Aubade folk; and quarrelling with the Wood folk, in whose soil the Court buries the dead it cannot fit under Gloaming."]]}, "peoples/kiln": {"title": "Kilnborn", "sub": "Human, changed by the fallen sun's heat. The ash-skinned people of the Deep's halls and forges.", "blocks": [["h", 2, "Origin"], ["p", "Before the Fall they were the hill people of the south: miners, masons and smiths who dug into the southern hills beside the [mole-folk](peoples/mole), and lived half above ground and half below. They called themselves the Delvers, and the Dial called them hillmen. The great forge was a quarry then, and the Ember Caldera a cold crater."], ["p", "On the day of the Fall, the sun's heat came up through the rock under the southern hills. The cold crater filled with fire from below: the Ember Caldera. The Delvers moved down toward the heat, built the great forge round it and called themselves the Underforge. Over one generation their skin went grey as ash and their eyes pale as a coal's edge, and the Dial began calling them by the name they now use themselves: **the Kilnborn**."], ["h", 2, "Homeland"], ["p", "[The Deep](realms/deep), at the sixth and seventh hours: the halls under the southern hills, the great forge in the Ember Caldera, the masons' halls, the Prism Stair, the Lamp Road, the Crystal Cavern, and the far halls of the lightless Deep, where the fire never reached. Kilnborn smiths work in every city on the Dial, and the Ring's iron is theirs."], ["h", 2, "Body"], ["p", "Short and broad, thick in the shoulder and the wrist, with big careful hands. Skin **ash-grey**, from pale dove to dark slate, and dry to the touch. Eyes pale amber, like the edge of a coal. Hair iron-grey or black, cut short or shaved for the forge; beards are kept long and braided by those who do not work the fire, short by those who do. Those who work the great forge for years show **ember seams**: thin lines in the skin at the knuckles, the throat and the collarbones that glow a dull orange when they are hot, and go dark when they cool. The Kilnborn of the far halls, who live where the Caldera's fire never came, kept their old colour: pale, from never seeing daylight, but not grey."], ["h", 2, "Lifespan and the Fall"], ["p", "About sixty-five years: the forge is hard on them, and the grey skin cracks in old age. The Fall made them, and they say so with pride: \"The sun fell to us.\" Their elders were Noon-touched like everyone; their children were born grey. The Kilnborn are the only people who speak of the Fall as a gift, and it makes the others uncomfortable."], ["h", 2, "Culture"], ["p", "Builders. A Kilnborn is judged by what they made and how long it stands. Houses are cut from the rock and passed down; a family's honour is its mark, cut on everything it makes. They are blunt, hospitable, quick to argue and slow to sulk. Meals are taken at long tables in the halls, under crystal light: mushrooms, root bread, goat from the hill farms, cheeses aged in the caves, and a thick dark beer. Their crafts are iron, copper, brass, glass from the Caldera, clockwork, golems and powder. The Brass Road to the Sands is their lifeline, and the Ring's iron their pride."], ["p", "They have two sore points. The Wood folk say the Kilnborn's mines eat the Wood's edge; and the Noonsworn want to carry the fire the Kilnborn live by up into the sky."], ["h", 2, "Faith"], ["p", "The **Anvil**. The world is a thing being made, and the maker's duty is to make it well. They honour the fire as a craftsman honours a good tool, and the fallen sun as the best tool the Dial ever had: their faith says the sun fell into the Deep to be **reforged**, and that it will rise as a sun underground, lighting the halls and warming the Dial through the rock. The smiths' priests are called Keepers of the Bellows. A small and growing teaching among the young, the Lamp-and-Key, says the fire is not theirs to keep, only theirs to tend until its owner comes back for it."], ["h", 2, "Names"], ["p", "Short, hard names, often of metals and tools: Brannoc, Bram, Ada, Hesk, Itzel (an old Caldera name for black glass), Kessa (a chain-maker's name). Family names are makers' marks: Bram Gerald's-Mason (he insists), Ada of the Turning Gear. A Kilnborn who makes something great takes its name: Brannoc's line is called the Ashen line after his first forge."], ["h", 2, "How they fight"], ["p", "Heavy and close, with hammers, mauls and axes, behind iron shields; and with engines: turrets, powder, golems, hooks. A Kilnborn army is slow and almost impossible to move. Their duellists are tanks and engineers, and they win by lasting."], ["h", 2, "Heroes and Climb people"], ["ul", ["**In the game:** [Brannoc](heroes/brannoc), [Bram](heroes/bram), [Ada](heroes/ada), and [Referee Whistler](heroes/referee-whistler), a mason's boy who came up the Brass Road to build the Ring and stayed to judge it.", "**New:** Itzel, Hesk, Kessa.", "**On the Climb:** the Deep's five, the Echo-Hermit, the Candle-Crowned, the Ferryman, the Crystal-Seller and the Firefly-Seller, all of the far halls (so not grey) ([the Deep](climb/deep))."]], ["h", 2, "Ties to other peoples"], ["p", "Brothers of the mole-folk in the old seams, though the mole-folk say the Kilnborn came second; partners of the Dune folk on the Brass Road; rivals of the Aubade folk over the sun's fire; enemies of the Wood folk at the Wood's edge."]]}, "peoples/longdead": {"title": "The Long Dead", "sub": "Not living. The bone-lords: the dead of the Dial whose will outlasted their flesh.", "blocks": [["h", 2, "Origin"], ["p", "Most of the dead lie down. A few do not. When someone dies with a purpose unfinished, and the purpose is strong enough, and they are buried where the dark is deep and the bone is kept, they sometimes **get up**. The Gloaming folk have known this for as long as they have buried their dead under the castle-city, and about 450 years before the Fall they made it a pact: the ossuaries under Gloaming were sealed with their first lord inside, and the dead who got up there were given halls, honour and work in return for keeping the city's dead quiet. Those who get up are **the Long Dead**. They are not many: a few hundred on the whole Dial."], ["h", 2, "Homeland"], ["p", "The ossuaries under [Gloaming](realms/gloaming): halls of bone older than the Court of Dusk, stacked skull on skull, lit by teal soulfire. Long Dead who have taken up other work live elsewhere: one keeps a ledger under the Ring, one poles a boat on rivers of light."], ["h", 2, "Body"], ["p", "A Long Dead looks like what they were, with the flesh **drawn back**. The newest are almost living: skin gone the colour and texture of old vellum, tight on the bone, sunken at the cheeks and eyes, the knuckles, the jaw and the brow showing bone through it. The oldest are bare bone, a skull with a jaw that still moves, and wear hoods and masks out of courtesy. All have **eyes of cold fire** in the sockets, teal in the ossuaries, ember-red in those who keep debts, pale blue in those who ferry. They do not breathe, do not age, and are very still when they are not moving."], ["h", 2, "Lifespan and the Fall"], ["p", "They do not end unless their purpose does, or someone breaks every bone. A Long Dead whose purpose is finished lies down, gladly or not. The Fall touched them as restlessness. Since the sun fell, the dead of the whole Dial have been uneasy, and many more have tried to get up than ever before: the drowned of the Coast, the soldiers of the Banners. Most of these are not Long Dead. They are **the Restless**: dead who got up without a will of their own, and walk because something keeps them walking. The Long Dead despise them, pity them, and (in [Mortis](heroes/mortis)'s case) employ them."], ["h", 2, "Culture"], ["p", "A people of memory and contract. Every Long Dead knows exactly why they got up, and keeps a **Reason**, written on a strip of linen inside the ribs, which they will show only to another of the Long Dead. They keep their promises absolutely, because a broken promise would end them. They are courteous, patient, dry in their humour, and very hard to hurry. They do not eat; they like to be offered food anyway. Their crafts are bone, carving, archive and law: half the contracts on the Dial are drawn up by someone who has been dead for two hundred years."], ["h", 2, "Faith"], ["p", "The Long Dead keep the **Unfinished**. They believe every life is a sentence, and that most end mid-word; the Long Dead are the ones who insisted on finishing theirs. They honour the Vigil of the Gloaming folk and are honoured in it. They have a quiet quarrel with Ostrel, the ferryman, who is one of them and holds that the kindest end of any sentence is a full stop."], ["h", 2, "Names"], ["p", "They keep the names they died with, and add the year: Mortis (an ossuary name, chosen; his living name is on a stone he does not visit), Ledger, Ostrel. They are addressed as \"the Long\" by the living, which they find funny."], ["h", 2, "How they fight"], ["p", "With bone and patience. The Long Dead raise walls and spires of bone, call the Restless, and do not tire or bleed. They are slow, they burn, and salt troubles them: a line of salt is a line most of them cannot cross, which is why the Truce hired Morwen."], ["h", 2, "Heroes and Climb people"], ["ul", ["**In the game:** [Mortis](heroes/mortis), and [Mr. Ledger](heroes/mr-ledger).", "**New:** Ostrel.", "**On the Climb:** none; the Climb's walking dead (the drowned dockers, the ashen soldiers, the Drowned Admiral) are the Restless, not the Long Dead ([bestiary](climb/bestiary))."]], ["h", 2, "Ties to other peoples"], ["p", "Bound to the Gloaming folk; respected and feared by the Dune folk, whose embalmers keep their kings whole for a different reason; avoided by the Briarkin; hated by [Anka](heroes/anka), who will not stay buried."]]}, "peoples/mole": {"title": "Mole-folk", "sub": "Not human. The Deep's first people, who call themselves the Loam.", "blocks": [["h", 2, "Origin"], ["p", "The mole-folk lived in the Deep before anyone, and say so whenever it is useful. Their **seam-songs**, sung while digging and passed from mother to daughter, go back about nine hundred years before the Fall by the Hourkeepers' reckoning, and the oldest of them already describe halls that are older still. They call themselves **the Loam**, and the world above ground \"the Thin\", because there is so little of it between you and the sky. Nobody knows where they came from. Their own story is that the first mole-folk dug up out of the dark below the world, found the Deep comfortable, and stopped."], ["h", 2, "Homeland"], ["p", "[The Deep](realms/deep): the deepest seams under the southern hills, below the Kilnborn's halls, where the rock is warm and the air is still. Their towns are warrens of round rooms joined by tunnels exactly as wide as a mole-folk's shoulders, which is why other peoples visit rarely. The Lamp Road, the great tunnel that runs from the Deep's mouth down to the crystal halls, is theirs, and they keep it open."], ["h", 2, "Body"], ["p", "The figure of a short, stout person, with a mole's head. Velvet fur, dark brown to black, short and dense, covering the head, the throat and the backs of the hands. A long, mobile muzzle with a small pink or rose nose, which they use more than their eyes. Small eyes, black and calm, that see poorly in bright light and well enough in the dark. Ears hidden in the fur. And the **claws**: hands broad as shovels with long curved nails, which they gild at the tips when they come of age. They are about a head shorter than a human and broader, and very strong for their size."], ["h", 2, "Lifespan and the Fall"], ["p", "About sixty years, and they age fast at the end. The Fall touched them first of all the peoples and least. They were deepest when the sun fell, and they were the first to see its light come down: it ran into the crystals of the Deep through the rock, and the dark halls they had known for nine hundred years were suddenly lit. The mole-folk call that day **the Shining**, and are divided about it. The old say it ruined the dark. The young, like [Mabel](heroes/mabel), say the light belongs to the miners who dug down to it. The Noon-touched among them are very few, because most of their elders were deep enough not to be touched by anything."], ["h", 2, "Culture"], ["p", "A people of mothers and seams. Every warren is run by its Old Mother, every seam by the family that opened it, and every quarrel by the oldest song that mentions it. They are polite, literal, curious and very hard to offend, except by a cave-in, which they take personally. They eat roots, grubs, fungus, cave fish and a kind of bread made from root flour that keeps for a year. They trade crystals and ore to the Kilnborn for tools, and the two peoples have mined side by side for nine centuries with exactly one long argument: who was there first."], ["h", 2, "Faith"], ["p", "The **Dark**. The mole-folk believe the world is a body and the Deep is its warm middle, and that the dark is not the absence of light but a thing in itself, comfortable and safe. They do not worship anything; they listen. A mole-folk prays by putting a paw to the rock and being quiet. Since the Shining a young teaching has grown, the Lamp, which says the light in the crystals was sent to them, and should be dug out, carried and shared, and certainly not given to the Noonsworn."], ["h", 2, "Names"], ["p", "Soft, round names with the sound of digging in them: Mabel, Tova, Odda, Bessom, Mudge. Family names are the seam: Mabel of the Deepest, Tova Lamp-Road. The Old Mothers are named only by their warren."], ["h", 2, "How they fight"], ["p", "From below. Mole-folk dig under the enemy and come up beneath them; they collapse floors, open pits, and fight close with their claws and short picks. In the open they are slow and know it, and they rarely fight in the open."], ["h", 2, "Heroes and Climb people"], ["ul", ["**In the game:** [Mabel](heroes/mabel).", "**New:** Tova.", "**On the Climb:** none of the Deep's five; the Echo-Hermit learned his way by echoes from a mole-folk Old Mother ([the Deep](climb/deep))."]], ["h", 2, "Ties to other peoples"], ["p", "Neighbours and rivals of the Kilnborn; suspicious of the Aubade folk, who want their light; friendly with the Briarkin, who also live under things; frightened of the Fallborn's Embers, because fire in a warren is death."]]}, "peoples/ninefold": {"title": "The Ninefold", "sub": "Not human. The cat-headed knights of the Dial: lynx on the Field, lion at the gate of Tamerit.", "blocks": [["h", 2, "Origin"], ["p", "Nobody, the Ninefold included, knows where the first of them came from. Their own legend is that the first Ninefold knight was a great lynx who saved a king of Harrowmark from drowning nine times, and was asked what she wanted in return; she asked for hands, to hold a sword, and a vow, to have something to keep. The king gave her both, and her children walked upright. Whatever the truth, by about 250 years before the Fall there were Ninefold knights in every court of the Dial, and they swore their oath at the **Keep of Nine** on the edge of the Field of Banners."], ["p", "There have never been many. A Ninefold mother has one child, rarely two, and many Ninefold never have any."], ["h", 2, "Homeland"], ["p", "The Keep of Nine, the old lynx knights' keep on a ridge above the Field of Banners, now half empty; and, for three generations, the gate of Tamerit in the Sands, which a lion line of the Ninefold has kept for the Dune Throne. Most Ninefold live wherever their oath has taken them."], ["h", 2, "Body"], ["p", "A tall, lithe human figure with a great cat's head. The **lynx line**: tawny or grey fur, black ear tufts, a ruff at the jaw, amber eyes. The **lion line**: heavier, gold fur, a mane that the men wear long and the women braid, eyes gold or green. Fur covers the head and throat and the backs of the hands, and the hands end in short claws they keep trimmed for the sword. They stand a little taller than a human and move a great deal better."], ["h", 2, "Nine lives"], ["p", "The Ninefold are named for it. A Ninefold who dies gets up again, eight times: the wound closes, the heart starts, and they are a little different after, as if a room in them had been shut. On the ninth death they stay dead. Every Ninefold knows how many lives they have left, and wears the count somewhere (a ring of studs on the collar, nine knots on a sword cord). They spend their lives, as the saying goes, like coin: on a vow, a wager or a friend. A Ninefold on their last life is called **one-left**, and is treated with great courtesy and kept out of fights."], ["h", 2, "Lifespan and the Fall"], ["p", "A Ninefold lives about eighty years if all their lives are kept, which none are. The Fall touched them strangely: the knights alive that day found their counts of lives had all gone back to nine. The Ninefold call it **the Noon Grace**, and a good many of them spent it in the War of the Banners, on both sides."], ["h", 2, "Culture"], ["p", "A people of vows. A Ninefold knight swears to a court, a cause or a person, and keeps it with great style until it is kept or broken; then they swear again elsewhere. They are proud, vain, courteous, curious, and fond of risk. They do not lie, but they enjoy misleading. They eat fish, fowl and cream, and drink almost nothing. Their art is the duel, which they treat as a conversation."], ["p", "The Ninefold are fewer every generation, and they know it. The Keep of Nine was full of knights in the year of the Fall and has eleven now. The young ones are trying to change that, without much luck."], ["h", 2, "Faith"], ["p", "None that they will name. They keep **the Count**: each life is a coin lent to them, to be spent well, and the ninth is returned to whoever lent it. Some say the lender was the sun, which would explain the Noon Grace."], ["h", 2, "Names"], ["p", "Old knightly names, often long, often shortened by friends: Sir Whiskers' full name is Sir Wystan Aurelio of Nine, which he will recite if asked and sometimes if not. The lions of the gate take gate names in the Dune tongue: Ramet means \"gate\"."], ["h", 2, "How they fight"], ["p", "As duellists, with rapiers and spears, light armour and a great deal of movement; they leap, land on their feet, and spend a life when a fight is worth it. In war they were the Dial's best scouts and its best rearguard."], ["h", 2, "Heroes and Climb people"], ["ul", ["**In the game:** [Sir Whiskers](heroes/sir-whiskers), lynx line.", "**New:** Ramet, lion line, captain of the gate of Tamerit.", "**On the Climb:** the War's Turncloak, a lynx knight who fought for both banners and spent eight lives doing it; he keeps his helm on ([the War](climb/war))."]], ["h", 2, "Ties to other peoples"], ["p", "They have served all of them. They are fondest of the Dune folk, who give them a gate, and of the Briarkin, who play their games; they are wary of the Long Dead, who know something about getting up again that the Ninefold would rather not learn."]]}, "peoples/north": {"title": "Northerners", "sub": "Human. The people of Frostfall, under the pole star, who write everything down.", "blocks": [["h", 2, "Origin"], ["p", "The Northerners came to the top of the Dial following the stars. Their first settlers, the Hourkeepers say, were herders who noticed that at Frostfall the stars turn round one fixed point, the pole star the Northerners call **the Nail**, and that a people who lived under the Nail could always know the hour. They built a stone ring on the shore of Frostfall Lake to watch the stars turn, about 1,200 years before the Fall; the Long Count begins with its first chart. The ring became the observatory, the observatory a town, and the town a people who measure."], ["h", 2, "Homeland"], ["p", "[Frostfall](realms/frostfall), at the twelfth hour of the Dial: the observatory and the frozen library on Frostfall Lake, the town of Hearthmere at the lake's south end, the reindeer moors, the ice coast, the Frostfall road that runs south past the Walking Wood to the Ring. Many Northerners live away from home as clerks, surveyors and tutors: a Northerner is welcome in every court that needs something counted."], ["h", 2, "Body"], ["p", "Broad and tall, with big hands and a slow, sure walk. Skin deep brown to warm umber, weathered at the cheeks. Their hair goes white early, often by thirty, and they wear it long in many thin braids, each tied with a bead for a skill learned. The mark of the people is the **star lines**: fine blue-black tattoos along the jaw and the backs of the hands that chart the sky at the hour of the wearer's birth, so that any Northerner can show you when they were born."], ["p", "The **lake-born** are a lineage of the Northerners from the shore villages of Frostfall Lake, the families that keep the ice: generations of the cold have left them frost-pale, nearly white-skinned with a blue undertone, and their hair is white from birth. The Winter Wardens have always come from the lake-born. [Isolde](heroes/isolde) and Saga are lake-born sisters."], ["h", 2, "Lifespan and the Fall"], ["p", "The longest-lived humans on the Dial, often past ninety; the cold keeps them, they say. The Fall touched them as time. At Frostfall the hours slip worse than anywhere, because the Hourkeepers can measure them, and a Northerner born after the Fall is taught as a child that the clock is a promise and not a fact. The observatory saw the Fall better than anyone, and wrote it down minute by minute; the record of the Fall, the **Noon Folio**, is the most read book in the frozen library. A few Northerners were touched more strangely: [Tempo](heroes/tempo) fell out of time at the moment of the Fall and has lived every moment twice."], ["h", 2, "Culture"], ["p", "A people of lists, charts and long winters. Every house has a clock and a shelf; every child learns to read before they learn to skate, and to skate before they learn to swim. Quarrels are settled by finding out who is right, which takes a long time and is considered entertaining. The winter is the season of stories, told in order, with dates. Their food is fish from under the ice, reindeer, barley, cloudberries and a strong black tea with salt and butter. Their crafts are lenses, paper, clocks, wool and ink. They are quiet, kind, stubborn and rarely surprised, and they are the Dial's best teachers."], ["h", 2, "Faith"], ["p", "The **Measure**. The Northerners hold that the world keeps an order, and that the order can be learned, and that learning it is the same as keeping it. Their temples are the observatory and the library. They pray by writing: on the longest night every Northerner writes down one true thing they learned that year, and the pages are bound into the year's book. Since the Fall the Measure has had to make room for the slipping hours, and has done so by measuring the slip. Most Northerners believe the sun must hang over the Tower again, because the shadow only falls when a sun hangs above it; but they want to know why it fell before anyone hangs it."], ["h", 2, "Names"], ["p", "Two-part given names, a sky word and a craft word, shortened in daily use: Lyra, Isolde, Saga, Thessa, Shiori (a scribe-name from the library's eastern script, given to calligraphers), Wick (a lamp-keeper's name). Family names are the hour of a birth: \"Lyra Ninth-and-a-half\" was born at half past the ninth hour. Nobody uses them aloud except clerks."], ["h", 2, "How they fight"], ["p", "Slowly and from a distance: with long spears on the ice, with bows from the observatory's terraces, and with the cold. Their warriors, the Wardens of the Winter, are few and fight to hold ground, not take it. Northern duellists are patient, read their opponents like a chart, and like to win in the last second."], ["h", 2, "Heroes and Climb people"], ["ul", ["**In the game:** [Lyra](heroes/lyra), [Isolde](heroes/isolde) (lake-born), [Tempo](heroes/tempo), [Shiori](heroes/shiori), [Wick](heroes/wick) (a lamp-keeper's son from Hearthmere who went south to keep doors).", "**New:** Saga (lake-born), Thessa.", "**On the Climb:** none of the people; the Sands' Star-Reader learned her stars at Frostfall and went south, though she is Dune folk by birth."]], ["h", 2, "Ties to other peoples"], ["p", "Friends of the Aubade folk; the Briarkin are their neighbours on the Frostfall road and the subject of many careful notes; the Kilnborn sell them lenses' brass; the Gloaming folk are their oldest quarrel, because the Court would keep the hour stopped."]]}, "peoples/wood": {"title": "Wood folk", "sub": "Human, changed by a forest that walks. The horned people of the Walking Wood and the high pastures.", "blocks": [["h", 2, "Origin"], ["p", "The Wood folk are the woodcutters, herders, hunters, charcoal burners and hive-keepers of the great western forest and the hill pastures above it. Before the Fall the forest stood still, and they were a plain human people with a reputation for silence and good cheese. They shared the forest with the [Briarkin](peoples/briar) of the Underbough by old treaty: the folk keep to the paths, the fae keep to the glades, and nobody whistles after dark."], ["p", "On the day of the Fall the Wood began to walk, as if it had felt the sun go and set off to find it. Within a year something else began: the Wood folk who had sworn themselves to the Wood, the wardens and hunters of the Moot, began to grow **horns**."], ["h", 2, "Homeland"], ["p", "[The Walking Wood](realms/wood), at the ninth and tenth hours, and the high pastures where the Wood meets the hills: the Antler Glades, where the Moot meets; the hive-trees; the charcoal clearings; the villages at the Wood's edge, which move when the Wood does; the shepherds' summer towns on the hills."], ["h", 2, "Body"], ["p", "Middling height and strong, with long arms. Skin ruddy to bark-brown, freckled. Hair brown, auburn or fox-red, worn long and braided with wooden beads. Eyes a moss green that is their own; the Wood folk say it came from looking at leaves. The mark of the people is the **horns**, and they come with an oath. A Wood person who swears the **Moot's oath**, to keep the Wood and be kept by it, grows horns within a year of swearing: branching antlers in the forest, curling ram horns among the hill shepherds, and on a few, like [Fenna](heroes/fenna), antlers that are living branches and put out leaves in spring. Horns are shed and regrown each year in the Wood, and kept for life in the hills. A Wood person who has not sworn, as most of the villagers and traders have not, grows none."], ["h", 2, "Lifespan and the Fall"], ["p", "About seventy years, a little longer for the sworn: the Wood keeps its own. The Fall made the Wood walk, and the folk have followed it ever since. Villages are built on skids; fields are planted where the Wood was last year; a farmer may wake to find an oak grove in the barley. The horns are the second change. The Wood folk take them as a sign that the Wood has chosen to keep its people, and they are proud of them. Hunters and smiths from elsewhere call them the Horned, not kindly."], ["h", 2, "Culture"], ["p", "Quiet, stubborn and cooperative: the Moot decides everything by talking until nobody objects, which can take a season. They are people of rules about the forest: a felled tree is paid for with a planted one; a hive is not robbed in the first frost; a stag is not hunted in the year it sheds. They eat bread, cheese, honey, mushrooms, venison, mutton and a hard cider. Their crafts are timber, charcoal, wool, amber, honey, wax and the long horns they blow to call the flocks and the Moot."], ["p", "They argue with each other about almost everything, and the arguments are friendly; [Fenna](heroes/fenna) and [Hank](heroes/hank) have shared a fire every winter for twenty years. They agree about the Tower, which they believe drinks the Dial."], ["h", 2, "Faith"], ["p", "The **Root**. The Wood folk believe the world is one living thing and the forest its oldest part, and that everything taken from it is owed back. They keep shrines at old trees, leave the first cut of every harvest at the Wood's edge, and bury their dead standing, with an acorn in each hand. Since the Fall they hold that the Wood walks to find the sun, and that the Tower, which stands where the sun fell, has roots that drink the Dial. The Moot wants those roots cut."], ["h", 2, "Names"], ["p", "Plain names, often of trees, birds and tools: Fenna, Hank (a hewer's name), Bo, Arden, Rowan, Tam. Family names are the place of birth, which moves: Fenna of the Third Glade, which is now somewhere else. The sworn take an oath-name from the horn they grow: Bo is called Bo Curlhorn in the hills."], ["h", 2, "How they fight"], ["p", "As hunters and woodsmen: bows from the trees, axes in the thickets, herds driven into the enemy, traps, horns to call each other through the forest. The Hunt of the Moot rides elk. A Wood folk fighter is hard to find, hard to move and harder to chase."], ["h", 2, "Heroes and Climb people"], ["ul", ["**In the game:** [Fenna](heroes/fenna), [Hank](heroes/hank), [Bo](heroes/bo).", "**New:** Arden.", "**On the Climb:** the Wood's five, the Moss-Abbess, the Path-Lighter, the Kiln-Mother, the Amber-Seller and the Charm-Pedlar, none of whom swore the Moot's oath; the Moss-Abbess's horn is an instrument, not her own ([the Wood](climb/wood))."]], ["h", 2, "Ties to other peoples"], ["p", "Old treaty-friends of the Briarkin; friends of the Coast folk; enemies of the Kilnborn at the Wood's edge; enemies of the Gloaming folk, whose Court buries its overflow dead in their soil; hosts of the Northerners on the Frostfall road."]]}};
